import type { MetadataRoute } from "next";

const CMS_URL = process.env.NEXT_PUBLIC_CMS_URL ?? "http://localhost:1337";

export default function robots(): MetadataRoute.Robots {
  return {
    rules: {
      userAgent: "*",
      allow: "/",
      // Authenticated dashboards and API routes; nothing to index there.
      disallow: ["/account", "/auth", "/api/", "/org/", "/partner/"],
    },
    // Generated by webtools-addon-sitemap in the CMS.
    sitemap: `${CMS_URL}/api/sitemap/index.xml`,
  };
}
